let data,view='activity',selected=null,activeLabels=[],evaluationLabel='mint';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),short=s=>s?`${s.slice(0,8)}…${s.slice(-6)}`:'Contract creation',pct=n=>n==null?'—':(n*100).toFixed(1)+'%',colors=['#3c64ad','#258780','#8266a6','#aa7148','#536c85'];
const labels=()=>data.taxonomy.labels,label=k=>labels().find(l=>l.id===k),name=k=>label(k)?.label||k,split=()=>$('#dataset').value,mode=()=>$('#mode').value,rows=()=>data.transactions.filter(t=>t.split===split()),chosen=t=>t[mode()]||[],englishRaw=o=>JSON.stringify(o,null,2).replace(/[\u3400-\u9fff]/g,c=>'\\u'+c.charCodeAt(0).toString(16).padStart(4,'0'));
function discrepancy(t){const unknown=t.unassessed||[];return {fp:t.predicted.filter(k=>!unknown.includes(k)&&!t.expected.includes(k)),fn:t.expected.filter(k=>!t.predicted.includes(k))};}
function changeView(v,fromHistory=false){const legacy=['explore','connection','connections','transactions'].includes(v);if(legacy){v='analysis';const query=location.hash.split('?')[1];history.replaceState(null,'','#analysis'+(query?'?'+query:''))}view=v;if(v!=='security'&&$('#security-case-drawer')?.open)$('#security-case-drawer').close();if(!fromHistory){const hash='#'+v;if(location.hash!==hash)history.pushState(null,'',hash);}window.scrollTo({top:0,behavior:'instant'});document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===(v==='action'?actionOrigin:v));b.setAttribute('aria-current',b.dataset.view===(v==='action'?actionOrigin:v)?'page':'false')});if(v==='analysis')renderAnalysis();if(v==='action')renderAction();if(v==='activity')renderActivity();if(v==='evaluation')renderEvaluation();if(v==='security')renderSecurity();$('#tooltip').hidden=true;}
function tooltip(el,text){el.onpointermove=e=>{const p=$('#tooltip');p.textContent=text;p.hidden=false;p.style.left=Math.max(8,Math.min(e.clientX+16,innerWidth-290))+'px';p.style.top=Math.min(e.clientY+18,innerHeight-85)+'px'};el.onpointerleave=()=>$('#tooltip').hidden=true;}
function bindSvg(el,fn){el.onclick=fn;el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();fn()}};}
function setLabels(ids){exactCombination=null;activeLabels=ids;networkFocus=[...ids];$('#search').value='';$('#error-filter').value='all';renderAnalysis();}
function renderAnalysis(){renderExplore();renderTransactions();}
function frequencies(){const counts=Object.fromEntries(labels().map(l=>[l.id,0]));rows().forEach(t=>new Set(chosen(t)).forEach(k=>counts[k]++));return counts;}
function renderExplore(){const counts=frequencies(),present=labels().filter(l=>counts[l.id]).sort((a,b)=>counts[b.id]-counts[a.id]||a.label.localeCompare(b.label));renderCloud(present,counts);renderLandscape(counts);renderDistribution();$('#clear-label').hidden=!activeLabels.length;
 $('#label-directory').innerHTML=labels().map(l=>`<button class="tag ${!counts[l.id]?'zero':''} ${activeLabels.includes(l.id)?'active':''}" data-directory="${l.id}">${esc(l.label)}<b>${counts[l.id]}</b></button>`).join('');document.querySelectorAll('[data-directory]').forEach(b=>b.onclick=()=>openAction(b.dataset.directory));}
function renderCloud(items,counts){const narrow=($('#cloud').clientWidth||900)<550,W=narrow?Math.max(340,$('#cloud').clientWidth):900,H=narrow?420:350,ctx=document.createElement('canvas').getContext('2d'),placed=[],max=Math.max(...Object.values(counts),1);let svg='';
 for(let index=0;index<items.length;index++){const l=items[index];let size=(narrow?16:20)+Math.sqrt(counts[l.id]/max)*(narrow?20:49),box=null;for(let attempt=0;attempt<4&&!box;attempt++){ctx.font=`500 ${size}px Manrope`;const w=ctx.measureText(l.label).width+17,h=size*1.18;for(let i=0;i<4500;i++){const angle=i*.18,r=4*Math.sqrt(i),x=W/2+Math.cos(angle)*r*2.8*(W/900),y=H/2+Math.sin(angle)*r*.95*(H/350);const b={x:x-w/2,y:y-h/2,w,h};if(b.x<10||b.y<10||b.x+w>W-10||b.y+h>H-10)continue;if(!placed.some(p=>b.x<p.x+p.w&&b.x+b.w>p.x&&b.y<p.y+p.h&&b.y+b.h>p.y)){box=b;break}}if(!box)size*=.82;}if(!box)continue;placed.push(box);svg+=`<text role="button" tabindex="0" aria-label="${esc(l.label)}, ${counts[l.id]} transactions" class="word" data-word="${l.id}" x="${box.x+box.w/2}" y="${box.y+box.h/2}" text-anchor="middle" dominant-baseline="central" fill="${actionColor(l.id)}" font-family="Manrope,sans-serif" font-weight="500" font-size="${size}" opacity="${!activeLabels.length||activeLabels.includes(l.id)?1:.25}">${esc(l.label)}</text>`;}
 $('#cloud').innerHTML=items.length?`<svg viewBox="0 0 ${W} ${H}" aria-label="Action frequency"><rect width="100%" height="100%" fill="transparent" role="button" tabindex="0" aria-label="Clear action selection"/>${svg}</svg>`:'<div class="empty"><strong>No labels in these transactions</strong>Try another action.</div>';
 document.querySelectorAll('[data-word]').forEach(e=>{bindSvg(e,()=>setLabels(activeLabels.length===1&&activeLabels[0]===e.dataset.word?[]:[e.dataset.word]));tooltip(e,`${name(e.dataset.word)} · ${counts[e.dataset.word]} / ${rows().length} transactions. Click to explore.`)});}
function renderLandscape(counts){const current=activeLabels[0],total=rows().length,tagged=rows().filter(t=>chosen(t).length).length,n=rows().filter(t=>activeLabels.every(k=>chosen(t).includes(k))&&(!exactCombination||[...chosen(t)].sort().join('|')===exactCombination)).length;
 $('#landscape-detail').innerHTML=current?`<p class="eyebrow">${activeLabels.length>1?'ACTION COMBINATION':'SELECTED ACTION'}</p><h2>${activeLabels.map(name).map(esc).join(' + ')}</h2><div class="big-number">${n}<small>transactions</small></div><div class="stat-pair"><span>Share of transactions</span><b>${pct(n/total)}</b></div><button class="text-button" id="inspect-selection">Explore transactions <span>↗</span></button>`:`<p class="eyebrow">OVERVIEW</p><div class="big-number">${Object.values(counts).filter(Boolean).length}<small>active actions</small></div><div class="stat-pair"><span>Transactions</span><b>${total}</b></div><div class="stat-pair"><span>Labeled transactions</span><b>${tagged}</b></div><div class="stat-pair"><span>Other transactions</span><b>${total-tagged}</b></div><button class="text-button" id="inspect-selection">Explore transactions <span>↗</span></button>`;$('#inspect-selection').onclick=()=>{if(!current)return changeView('activity');if(activeLabels.length===1&&!exactCombination)return openAction(current);const evidence=$('.relation-evidence');evidence.open=true;evidence.scrollIntoView({behavior:'smooth',block:'center'})};}
function renderConnections(items,counts){const top=items.slice(0,10),W=580,H=310,points=Object.fromEntries(top.map((l,i)=>{const a=-Math.PI/2+2*Math.PI*i/top.length;return [l.id,{x:W/2+185*Math.cos(a),y:H/2+112*Math.sin(a),a}]}));let links=[],svg='';for(let a=0;a<top.length;a++)for(let b=a+1;b<top.length;b++){const n=rows().filter(t=>chosen(t).includes(top[a].id)&&chosen(t).includes(top[b].id)).length;if(n)links.push({a:top[a].id,b:top[b].id,n});}
 links.sort((a,b)=>b.n-a.n);for(const e of links.slice(0,22)){const a=points[e.a],b=points[e.b],focus=!activeLabels.length||[e.a,e.b].some(k=>activeLabels.includes(k));svg+=`<path role="button" tabindex="0" aria-label="${esc(name(e.a)+' with '+name(e.b))}, ${e.n} transactions" data-pair="${e.a},${e.b}" class="network-link" d="M${a.x},${a.y} Q290,155 ${b.x},${b.y}" fill="none" stroke="#4c83aa" stroke-width="${1+Math.sqrt(e.n)*1.1}" opacity="${focus?.45:.07}"/>`;}
 top.forEach((l,i)=>{const p=points[l.id];svg+=`<g role="button" tabindex="0" data-node="${l.id}" aria-label="Explore ${esc(l.label)}"><circle cx="${p.x}" cy="${p.y}" r="${5+Math.sqrt(counts[l.id])*2}" fill="${actionColor(l.id)}" opacity=".9"/><text class="network-label" x="${p.x}" y="${p.y+(p.y>155?29:-21)}" text-anchor="middle">${esc(l.label)}</text></g>`});
 $('#connections').innerHTML=links.length?`<svg viewBox="0 0 ${W} ${H}">${svg}</svg>`:'<div class="empty"><strong>No co-occurring labels</strong>No transactions contain multiple actions.</div>';
 document.querySelectorAll('[data-pair]').forEach(e=>{bindSvg(e,()=>{exactCombination=null;$('#search').value='';$('#error-filter').value='all';activeLabels=e.dataset.pair.split(',');changeView('connection')});const x=links.find(l=>l.a+','+l.b===e.dataset.pair);tooltip(e,`${name(x.a)} + ${name(x.b)} · ${x.n} transactions`)});document.querySelectorAll('[data-node]').forEach(e=>bindSvg(e,()=>setLabels([e.dataset.node])));}
function renderCombinations(){const map=new Map();rows().forEach(t=>{const tags=[...chosen(t)].sort();if(!tags.length)return;const key=tags.join('|');map.set(key,(map.get(key)||0)+1)});const top=[...map].sort((a,b)=>b[1]-a[1]).slice(0,6),max=top[0]?.[1]||1;$('#combinations').innerHTML=top.map(([k,n])=>`<button class="combo-row" data-combo="${k}"><span><span class="combo-name">${k.split('|').map(name).map(esc).join(' + ')}</span><span class="combo-track"><i style="width:${n/max*100}%"></i></span></span><strong>${n}</strong></button>`).join('')||'<p class="empty">No labeled combinations.</p>';document.querySelectorAll('[data-combo]').forEach(b=>b.onclick=()=>{activeLabels=b.dataset.combo.split('|');$('#search').value='';exactCombination=b.dataset.combo;$('#error-filter').value='all';changeView('connection')});}
let exactCombination=null;
function renderTransactions(){const q=$('#search').value.toLowerCase(),kind=$('#error-filter').value;const filtered=rows().filter(t=>{const d=discrepancy(t),all=t.predicted;return `${t.id} ${all.map(k=>name(k)+' '+k).join(' ')}`.toLowerCase().includes(q)&&activeLabels.every(k=>chosen(t).includes(k))&&(!exactCombination||[...chosen(t)].sort().join('|')===exactCombination)&&(kind!=='errors'||d.fp.length+d.fn.length)&&(kind!=='unknown'||t.unassessed?.length)});$('#result-count').textContent=`${filtered.length} transactions`;$('#active-filter').textContent=activeLabels.length?(exactCombination?'Exact: ':'Contains: ')+activeLabels.map(name).join(' + '):'';
 if(!filtered.some(t=>t.id===selected))selected=filtered[0]?.id||null;
 $('#tx-list').innerHTML=filtered.map(t=>{const d=discrepancy(t);return `<button class="tx-button ${t.id===selected?'selected':''}" data-tx="${t.id}"><span class="tx-action">${t.predicted.length?t.predicted.map(name).map(esc).join(' + '):'Unclassified action'}</span><small>${short(t.id)} · ${t.state.transaction.timestamp.slice(0,10)}</small></button>`}).join('')||'<div class="empty">No matches</div>';document.querySelectorAll('[data-tx]').forEach(b=>b.onclick=()=>{selected=b.dataset.tx;history.replaceState(null,'','#connection?tx='+selected);renderTransactions()});if(selected)renderTransaction(data.transactions.find(t=>t.id===selected));else $('#tx-detail').innerHTML='<div class="empty"><strong>No matching transactions</strong>Clear the action selection or try a different search.</div>';}
function chips(ids,cls=''){return tagList(ids)||'<span class="small">None</span>'}
function renderTransaction(t){const s=t.state,events=[...new Set(s.logs.filter(l=>l.decoded).map(l=>l.decoded.method_call.split('(')[0]))];
 $('#tx-detail').innerHTML=`<div class="tx-header"><div><p class="eyebrow">TRANSACTION / ${short(t.id)}</p><h2>${t.predicted.length?t.predicted.map(name).map(esc).join(' + '):'Unclassified action'}</h2></div><a target="_blank" rel="noopener" href="https://hsk.blockscout.com/tx/${t.id}">Open in explorer ↗</a></div><div class="meta"><span>Block ${s.transaction.block_number.toLocaleString()}</span><span>${esc(s.transaction.timestamp.slice(0,19).replace('T',' '))} UTC</span><span>${s.transaction.status==='ok'?'Succeeded':esc(s.transaction.status)}</span></div><div class="asset-panel"><div class="asset-head"><h3>Asset flow</h3><select id="asset-select" aria-label="Select asset for flow"></select></div><div id="asset-flow"></div></div><div class="section-line"><h3>Transaction actions</h3><div class="label-set">${chips(t.predicted)}</div></div><div class="evidence-grid"><div><h3>From</h3><a class="address-link" target="_blank" rel="noopener" href="https://hsk.blockscout.com/address/${esc(s.from)}">${esc(s.from)}</a></div><div><h3>To</h3>${s.to?`<a class="address-link" target="_blank" rel="noopener" href="https://hsk.blockscout.com/address/${esc(s.to)}">${esc(s.to)}</a>`:'Contract creation'}</div></div><details><summary>Execution details</summary><p class="small">${s.logs.length} event logs · ${s.internal_calls.length} internal calls · ${s.token_transfers.length} token transfers</p><p class="small">${esc(events.join(' · ')||'No decoded events')}</p><pre>${esc(englishRaw(s.transaction.decoded_input||{method:s.transaction.method}))}</pre></details>`;
 const flows=transactionFlows(s),assets=[...new Map(flows.map(e=>[e.key,e.asset])).entries()];$('#asset-select').innerHTML=assets.map(([k,n])=>`<option value="${esc(k)}">${esc(n)}</option>`).join('');$('#asset-select').hidden=!assets.length;const draw=()=>renderAssetFlow(flows.filter(e=>e.key===$('#asset-select').value),s);$('#asset-select').onchange=draw;draw();}
function amount(value,decimals=18){try{const n=BigInt(value||0),d=Math.max(0,Math.min(80,Number(decimals)||0)),base=10n**BigInt(d),whole=n/base,frac=d?(n%base).toString().padStart(d,'0').slice(0,6).replace(/0+$/,''):'';return n!==0n&&whole===0n&&!frac?'<0.000001':whole.toLocaleString()+(frac?'.'+frac:'')}catch{return String(value||'0')}}
function transactionFlows(s){const e=[],add=(from,to,v,asset,key='native',dec=18,nft=false,qty)=>{if(!from||!to)return;e.push({from:from.toLowerCase(),to:to.toLowerCase(),asset,key,amount:nft?`${qty||'1'} × #${v}`:amount(v,dec)})};if(s.transaction.status==='ok'&&BigInt(s.transaction.value||0)>0)add(s.from,s.to,s.transaction.value,'HSK');for(const c of s.internal_calls||[])if(c.success===true&&['call','create','create2'].includes(c.type)&&BigInt(c.value||0)>0)add(c.from,c.to||c.created_contract?.hash,c.value,'HSK');for(const t of s.token_transfers||[]){const nft=/721|1155/.test(t.token?.type||'');add(t.from,t.to,nft?t.total?.token_id:t.total?.value,t.token?.symbol||t.token?.name||'Token',t.token?.address_hash||t.token?.address||t.token?.symbol||'token',t.token?.decimals,nft,t.total?.value)}return e;}
function renderAssetFlow(edges,s){if(!edges.length){$('#asset-flow').innerHTML='<div class="empty"><strong>No observed asset transfers</strong>The transaction may change permissions or state, or may have failed.</div>';return}const sources=[...new Set(edges.map(e=>e.from))],targets=[...new Set(edges.map(e=>e.to))],left=sources.slice(0,5),right=targets.slice(0,5),y=(arr,a)=>45+(arr.indexOf(a)+.5)*210/arr.length;let svg='';for(const e of edges.filter(e=>left.includes(e.from)&&right.includes(e.to)).slice(0,35))svg+=`<path class="flow-edge" data-from="${e.from}" data-to="${e.to}" d="M165,${y(left,e.from)} C310,${y(left,e.from)} 330,${y(right,e.to)} 475,${y(right,e.to)}" marker-end="url(#arrow)"><title>${esc(e.amount+' '+e.asset)}</title></path>`;
 const node=(a,x,arr)=>`<g class="flow-node" data-address="${a}" role="button" tabindex="0" aria-label="Focus ${a}"><circle cx="${x}" cy="${y(arr,a)}" r="7"/><text class="flow-address" x="${x===165?x-17:x+17}" y="${y(arr,a)+4}" text-anchor="${x===165?'end':'start'}">${short(a)}</text></g>`;svg+=left.map(a=>node(a,165,left)).join('')+right.map(a=>node(a,475,right)).join('');$('#asset-flow').innerHTML=`<svg viewBox="0 0 640 300" aria-label="Directed asset transfers"><defs><marker id="arrow" viewBox="0 0 10 10" refX="13" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10" fill="#258780"/></marker></defs><text x="35" y="25" class="flow-role">FROM</text><text x="500" y="25" class="flow-role">TO</text>${svg}</svg><p class="small">${edges.length} transfers · Equal-width links show direction, not value. ${sources.length>5||targets.length>5||edges.length>35?'Graph limited to 5 addresses per side and 35 links. Full transfer list below.':''}</p><div class="transfer-list">${edges.map(e=>`<div class="transfer-row" data-flow-from="${e.from}" data-flow-to="${e.to}"><span>${short(e.from)} → ${short(e.to)}</span><b>${esc(e.amount+' '+e.asset)}</b></div>`).join('')}</div>`;let focus=null;document.querySelectorAll('[data-address]').forEach(n=>bindSvg(n,()=>{focus=focus===n.dataset.address?null:n.dataset.address;document.querySelectorAll('.flow-edge').forEach(e=>e.style.opacity=!focus||[e.dataset.from,e.dataset.to].includes(focus)?'.65':'.05');document.querySelectorAll('[data-flow-from]').forEach(e=>e.hidden=!!focus&&![e.dataset.flowFrom,e.dataset.flowTo].includes(focus));document.querySelectorAll('[data-address]').forEach(e=>e.classList.toggle('focused',e.dataset.address===focus))}));}
function wilson(k,n){if(!n)return 'No samples';const z=1.959963984540054,p=k/n,d=1+z*z/n,c=(p+z*z/(2*n))/d,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return `${pct(Math.max(0,c-h))}–${pct(Math.min(1,c+h))}`;}
function refresh(){activeLabels=[];exactCombination=null;$('#notice').textContent=split()==='coverage'?'Targeted coverage sample · frequency is not representative of HSK activity.':split()==='random'?'Random final sample · only one confirmed positive label; interpret scores with sample counts.':'Regression sample · previously used for tuning; not an independent test.';renderAnalysis();resetActivity();if(view==='evaluation')renderEvaluation();}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>changeView(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();changeView('activity')};$('#dataset').onchange=refresh;$('#mode').onchange=refresh;$('#clear-label').onclick=()=>{exactCombination=null;setLabels([])};$('#search').oninput=renderTransactions;$('#error-filter').onchange=renderTransactions;$('#reset-filters').onclick=()=>{activeLabels=[];exactCombination=null;$('#search').value='';$('#error-filter').value='all';renderTransactions()};
document.addEventListener('DOMContentLoaded',async()=>{try{const r=await fetch('data.json');if(!r.ok)throw Error('Data unavailable');data=await r.json();await document.fonts.ready;refresh();restoreRoute()}catch(error){console.error(error);$('#notice').hidden=false;$('#notice').parentElement.hidden=false;$('#notice').textContent='Unable to load transactions. Please refresh.'}});

let resizeTimer;window.addEventListener("resize",()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(data&&view==='analysis')renderAnalysis()},150)});

function restoreRoute(){const [route,query]=(location.hash.slice(1)||'activity').split('?');const requested=new URLSearchParams(query||'').get('tx');if(requested&&rows().some(t=>t.id===requested)){activeLabels=[];exactCombination=null;$('#search').value='';selected=requested;}if(route==='action'){selectedAction=new URLSearchParams(query||'').get('id');}if(route==='security'){const p=new URLSearchParams(query||'');securityGroup=p.get('pattern')||'reentrancy';securityVariant=p.get('variant')==='benign'?'benign':'attack';securityStep=0;securityCaseAt=Number(new URLSearchParams(query||'').get('at'))||null;securityCaseId=p.get('case')||(p.has('pattern')?securityGroup+'-'+securityVariant:null)}changeView(['analysis','explore','activity','connection','connections','evaluation','action','security'].includes(route)?route:route==='transactions'?'connection':'activity',true)}window.addEventListener('popstate',()=>{if(data)restoreRoute()});
